fn handle_line_defense(_version, rnd, player, data, line, _debug) -> bool

// --- 544: 그 라인이 이 게임 모드에 존재하는가 ---
if !rule_scope::line_exists(data.context, line) { return false }        // %13

// --- 549: rule_scope::morgard_exists(data, 1 - player.info.team) (전부 인라인) ---
//   (a) 튜토리얼 게이트: TutorialType::spawn_epic(context.tutorial)
let t = data.context.tutorial as u8                                     // GameContext+0x38
if (t - 1) < 6 { return false }             // 태그 1..=6 = 에픽 없는 튜토리얼
//   (b) 게임모드가 Moba 인가
let game = data.cache.game                  // &dyn AbstractGame (data=+0x0, vtable=+0x8)
let mode = game.vtable[0x40 /*get_game_mode*/](game.data)   // GameMode {tag, ptr}
if mode.tag != 0 { core::option::unwrap_failed() }   // GameMode::as_moba().unwrap()
let moba: &MobaMode = mode.payload                   // enum+0x8
//   (c) 적팀에 모르가드(에픽) 버프가 남아 있는가
let team = player.info.team                          // PlayerState+0x930
let enemy = 1 - team
if enemy >= 2 { panic_bounds_check(enemy, 2) }
if moba.epic_minion_buff_time[enemy] == 0 { return false }   // remain_epic_time(enemy)

// --- 553: 이 라인의 아군 타워 (AbstractGameWithCache::tower, simulation.rs:1822, 인라인) ---
if team >= 2 { panic_bounds_check(team, 2) }
let (a, b) = match line {                    // 오프셋은 phi 로 접혀 있음
    Top    => (0x180, 0x190),
    Mid    => (0x1a0, 0x1b0),
    Bottom => (0x1c0, 0x1d0),
}
let line_tower: Option<&Entity> = cache[a][team].or(cache[b][team])   // %63

// --- 554~559: 없으면 라인 시작점에서 가장 가까운 아군 트윈타워로 대체 ---
let vec = cache.twin_towers[team]            // AbstractGameWithCache+0x130, stride 32
let nearest: Option<&&Entity> =
    vec.iter().min_by_key(|e| {              // closure$0 @555, 본체는 m12.ll 30536~30687
        let p = line.get_start_position(context.setting, player.info.team);   // 556
        let dx = abs_diff(e.x, p.0); let dy = abs_diff(e.y, p.1);
        dx*dx + dy*dy                        // 557 (utils.rs:9 인라인)
    })
    // 동점이면 첫 원소 유지(compare(acc,new) <= Equal 이면 acc 유지)
let tower: Option<&Entity> = line_tower.or(nearest.copied())   // 559 (.or @554)

// --- 565: 타워가 하나도 없으면 판정 불가 ---
if tower.is_none() { return false }          // unwrap 의 패닉 경로는 소거됨
let tower: &Entity = tower.unwrap()          // %110

// --- 567: 이 라인에 실제 위협이 있는가 ---
if !has_line_defense_threat(player, data, line, tower.id /*Entity+0x5c0*/) { return false }

// --- 571~572: 타워 근처에 보이는 적 챔프 수 ---
let champs = cache.champions(enemy /*=1-team*/, context.pool)   // bumpalo::Vec<&Entity>
let mut near_enemy_champion = 0usize
for e in champs {                            // 인덱스 루프로 펼쳐짐
    if !data.blackboard[enemy].is_recent_visible(game, player, e) { continue }
    let dx = abs_diff(e.x, tower.x); let dy = abs_diff(e.y, tower.y)
    if dx*dx + dy*dy < 40000000001 { near_enemy_champion += 1 }   // Entity::distance_sq
}
// 573: champs(bumpalo Vec) drop

// --- 575~578: 전략에 따라 임계치를 바꿔 최종 판정 ---
let strategy = player.strategy(rnd, game)                      // Strategy(24B) sret
let defense  = strategy.morgard_defense                        // Strategy+0xe
return if defense == Battle {                                  // 태그 1
    (near_enemy_champion - 1) < 2      // near ∈ {1, 2}
} else {                                                       // Gather(태그 0)
    near_enemy_champion > 1            // near >= 2
}
